<script setup lang="ts">
import { computed, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { getLogs } from '../api/wcs'; import type { LogRecord } from '../types/wcs';
const grade=ref('INFO'); const msgSnip=ref('%'); const max=ref(200); const rows=ref<LogRecord[]>([]); const sortKey=ref<keyof LogRecord>('id'); const sortOrder=ref<'ascending'|'descending'>('descending'); const options=['INFO','ERROR','WARN','FATAL','DEBUG','ALL'];
const sortedRows=computed(()=>[...rows.value].sort((a,b)=>String(a[sortKey.value]??'').localeCompare(String(b[sortKey.value]??''),'zh-CN',{numeric:true})*(sortOrder.value==='ascending'?1:-1))); function sortChange({prop,order}:{prop:keyof LogRecord;order:'ascending'|'descending'|null}){if(order){sortKey.value=prop;sortOrder.value=order;}}
async function query(){try{rows.value=await getLogs({grade:grade.value==='ALL'?'%':grade.value,msgSnip:msgSnip.value||'%',logCntMax:max.value});}catch{ElMessage.error('日志查询失败');}}
</script>
<template><section class="page-view"><div class="page-heading"><div><h1>日志查询</h1></div></div><div class="content-card filter-card"><el-form class="filter-form" label-position="top" @submit.prevent="query"><el-form-item label="日志级别"><el-select v-model="grade" class="filter-control"><el-option v-for="item in options" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="消息片段"><el-input v-model="msgSnip" class="filter-control message-input" placeholder="默认查询全部消息" clearable/></el-form-item><el-form-item label="返回数量"><el-input-number v-model="max" class="filter-control" :min="1" :max="10000" controls-position="right"/></el-form-item><el-form-item class="filter-submit"><el-button type="primary" @click="query">查询日志</el-button></el-form-item></el-form></div><div class="content-card mobile-scroll log-table"><el-table :data="sortedRows" border @sort-change="sortChange"><el-table-column prop="id" label="ID" min-width="90" sortable="custom"/><el-table-column prop="date" label="时间" min-width="170" sortable="custom"/><el-table-column prop="grade" label="级别" min-width="100" sortable="custom"/><el-table-column prop="source" label="来源" min-width="220" sortable="custom"/><el-table-column prop="message" label="消息" min-width="360" sortable="custom"/></el-table></div></section></template>
<style scoped>.filter-card{margin-bottom:20px;padding:20px 22px}.filter-form{display:flex;align-items:flex-end;gap:16px}.filter-form :deep(.el-form-item){margin:0}.filter-control{width:170px}.message-input{width:300px}.filter-submit{padding-bottom:0}.log-table{padding:0}.log-table :deep(.el-table__body-wrapper){min-height:180px}@media(max-width:768px){.filter-card{padding:16px}.filter-form{align-items:stretch;flex-direction:column;gap:4px}.filter-control,.message-input,.filter-submit,.filter-submit .el-button{width:100%}.filter-submit{margin-top:10px!important}.log-table{margin-top:16px}}</style>
